'use strict';
const mongoose = require('../../lib/db');

const KINDS = ['song', 'quran', 'podcast', 'lesson', 'video', 'other'];
const KIND_SOURCES = ['auto', 'rule'];
const RULE_FIELDS = ['title', 'artist', 'pkg'];
const REASONS = ['bored', 'stressed', 'driving', 'working', 'habit', 'other'];

// One stretch of continuous playback, recorded by the phone (notification-access media listener).
const listenSegmentSchema = new mongoose.Schema(
  {
    userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    // Generated by the phone: makes the upload idempotent.
    clientId: { type: String, required: true },
    pkg: { type: String, default: '' },
    appLabel: { type: String, default: '' },
    title: { type: String, default: '' },
    artist: { type: String, default: '' },
    album: { type: String, default: '' },
    startAt: { type: Date, required: true },
    endAt: { type: Date, required: true },
    seconds: { type: Number, required: true, min: 0 },
    // Local date (user's timezone) of startAt.
    date: { type: String, required: true },
    // Was inside a green (song-free) window; the phone splits segments at window edges.
    green: { type: Boolean, default: false },
    greenLabel: { type: String, default: null },
    kind: { type: String, enum: KINDS, required: true },
    kindSource: { type: String, enum: KIND_SOURCES, default: 'auto' },
  },
  { timestamps: true },
);
listenSegmentSchema.index({ userId: 1, clientId: 1 }, { unique: true });
listenSegmentSchema.index({ userId: 1, date: 1 });

// "Always treat this title / artist / app as <kind>".
const listenRuleSchema = new mongoose.Schema(
  {
    userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    field: { type: String, enum: RULE_FIELDS, required: true },
    // Normalized (see logic.normalize).
    value: { type: String, required: true },
    kind: { type: String, enum: KINDS, required: true },
  },
  { timestamps: true },
);
listenRuleSchema.index({ userId: 1, field: 1, value: 1 }, { unique: true });

// The answer to the one-tap "why?" prompt after a long song session.
const listenReasonSchema = new mongoose.Schema(
  {
    userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    date: { type: String, required: true },
    at: { type: Date, required: true },
    reason: { type: String, enum: REASONS, required: true },
    songSeconds: { type: Number, default: 0, min: 0 },
  },
  { timestamps: { createdAt: true, updatedAt: false } },
);
listenReasonSchema.index({ userId: 1, date: 1 });

const screenAppSchema = new mongoose.Schema(
  {
    pkg: { type: String, required: true },
    label: { type: String, default: '' },
    seconds: { type: Number, default: 0, min: 0 },
    opens: { type: Number, default: 0, min: 0 },
  },
  { _id: false },
);

// Per-day screen time of the watch apps, computed on the phone from Usage Access and upserted.
const screenDaySchema = new mongoose.Schema(
  {
    userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    date: { type: String, required: true },
    apps: { type: [screenAppSchema], default: [] },
    firstPickupAt: { type: Date, default: null },
    firstApp: {
      type: new mongoose.Schema({ pkg: { type: String, required: true }, label: { type: String, default: '' } }, { _id: false }),
      default: null,
    },
    // Watch-app seconds after the planned bedtime that night.
    lateSeconds: { type: Number, default: 0, min: 0 },
  },
  { timestamps: { createdAt: false, updatedAt: true } },
);
screenDaySchema.index({ userId: 1, date: 1 }, { unique: true });

module.exports = {
  ListenSegment: mongoose.model('ListenSegment', listenSegmentSchema),
  ListenRule: mongoose.model('ListenRule', listenRuleSchema),
  ListenReason: mongoose.model('ListenReason', listenReasonSchema),
  ScreenDay: mongoose.model('ScreenDay', screenDaySchema),
  KINDS, KIND_SOURCES, RULE_FIELDS, REASONS,
};
